/**
* Computes the modified Bessel function of the second kind of order one.
*
* ## Notes
*
* -   The function has a logarithmic singularity at `x = 0`.
* -   Accuracy for subnormal `x` is poor due to underflow.
*
* @param x    input value
* @return     evaluated modified Bessel function
*
* @example
* double y = stdlib_base_besselk1( 1.0 );
* // returns ~0.6019
*/
double stdlib_base_besselk1( const double x ) {
	double a;
	double r;
	double ex;

	if ( x < 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	if ( x == 0.0 ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	if ( x == STDLIB_CONSTANT_FLOAT64_PINF ) {
		return 0.0;
	}

	if ( x <= 1.0 ) {
		a = 0.25 * x * x;
		a = ( ( rational_p1q1( a ) + Y_SMALL ) * a * a ) + ( 0.5 * a ) + 1.0;
		a *= 0.5 * x;

		return ( rational_p2q2( x * x ) * x ) +
			( 1.0 / x ) +
			( stdlib_base_ln( x ) * a );
	}
	r = rational_p3q3( 1.0 / x );

	if ( x < LOG_MAX ) {
		return ( r + Y_LARGE ) *
			stdlib_base_exp( -x ) /
			stdlib_base_sqrt( x );
	}

	/* overflow-safe */
	ex = stdlib_base_exp( -0.5 * x );
	return ( r + Y_LARGE ) *
		ex / stdlib_base_sqrt( x ) * ex;
}
